let gridsize = 80;
let grid = [gridsize * gridsize];

let blobs = [];
let numblobs = 10;

function setup() {
	createCanvas(max(windowWidth, windowHeight), max(windowWidth, windowHeight));
	pixelDensity(1);
	for (let i = 0; i < sq(gridsize); i++) {
		grid[i] = 0
	}
	blobs = [];
	for (let i = 0; i < numblobs; i++) {
		blobs.push(new blob());
	}
	background("#F8F8DD");
	textFont('Georgia');
}

function draw() {
	background("#F8F8DDCC");
	translate(width * 0.05, height * 0.05);
	scale(0.9);
	calcgrid();
	drawgrid();
	frame();
	for (let b of blobs) {
		b.move();
	}
}

function frame() {
	push();
	noStroke();
	let c = color("#554242");
	textAlign(CENTER, CENTER);
	let step = width / gridsize;
	textSize(1.0 * step);
	for (let i = -2; i < gridsize + 2; i++) {
		c.setAlpha(random(128, 255));
		fill(c);
		let p = step * (i + 0.5) + random(-1, 1);
		text("=", p, -2 * step + 0.5);
		text("=", p, (gridsize + 2) * step + 0.5);
		text("l", -2 * step + 0.5, p);
		text("l", (gridsize + 2) * step + 0.5, p);
	}
	pop();
}

function drawgrid() {
	push();
	noStroke();
	let c = color("#554242");
	textAlign(CENTER, CENTER);
	let step = width / gridsize;
	textSize(1.0 * step);
	for (let i = 0; i < sq(gridsize); i++) {
		c.setAlpha(random(128, 255));
		fill(c);
		let x = step * (i % gridsize + 0.5) + random(-1, 1);
		let y = step * (floor(i / gridsize) + 0.5) + random(-1, 1);
		let t = " ";
		if (grid[i] > 11 * numblobs) t = "@"
		else if (grid[i] > 10.5 * numblobs) t = "%"
		else if (grid[i] > 10 * numblobs) t = "#"
		else if (grid[i] > 9.5 * numblobs) t = "+"
		else if (grid[i] > 9 * numblobs) t = "∙"

		if (random() < 0.005) t = String.fromCharCode(floor(random(33, 127)));

		text(t, x, y);
	}
	pop();
}

function calcgrid() {
	for (let i = 0; i < sq(gridsize); i++) {
		grid[i] = 0;
		let x = i % gridsize;
		let y = floor(i / gridsize);
		for (let b of blobs) {
			grid[i] += numblobs / map(dist(x, y, b.pos.x, b.pos.y), 0, b.strength, 0.001, 1);
		}
	}
}

class blob {
	constructor() {
		this.pos = createVector(random(gridsize), random(gridsize));
		this.strength = random(gridsize * 0.3, gridsize * 0.5);
		this.dir = p5.Vector.random2D();
		this.drift = random(-1, 1) * 0.1
	}

	move() {
		this.dir.rotate(random(this.drift));
		this.pos.add(this.dir);
		this.pos.x = constrain(this.pos.x, 0, gridsize);
		this.pos.y = constrain(this.pos.y, 0, gridsize);
	}
}

//disable default right mouse click
document.addEventListener("contextmenu", (event) => event.preventDefault(), "true")

//left click restarts, right click does an image capture
let lapse = 0; // mouse timer
function mousePressed() {
	if (millis() - lapse > 400) {
		lapse = millis();
		if (mouseButton === RIGHT) {
	    save("img_" + year() + nf(month(), 2) + nf(day(), 2) + nf(hour(), 2) + nf(minute(), 2) + nf(second(), 2) + ".png");
		} else if (mouseButton === CENTER) {
		} else {
			setup(); // start a new image
		}
	}
	return (false)
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            return createGraphics(10, 10);
        }
        return window._origGet.apply(this, args);
    };
}
